/** UI for deterministic predicates; existing predicates round-trip without simplification. */
static final class NotificationRuleEditor {
 final Activity a;final LinearLayout rows;final AiosUi.Choice mode;final List<Row> values=new ArrayList<>();
 final String[] fields={"title","text"},ops={"contains","not_contains","equals","starts_with","ends_with"};
 NotificationRuleEditor(Activity activity,LinearLayout parent,JSONObject trigger){a=activity;
  parent.addView(AiosUi.fieldLabel(a,a.getString(R.string.filter_heading)));parent.addView(AiosUi.secondary(a,a.getString(R.string.filter_hint)));
  mode=new AiosUi.Choice(a,new String[]{a.getString(R.string.filter_all),a.getString(R.string.filter_any)},trigger!=null&&trigger.optString("condition_mode").equals("any")?1:0,null);parent.addView(mode.view);
  rows=AiosUi.column(a);parent.addView(rows);JSONArray conditions=trigger==null?null:trigger.optJSONArray("conditions");if(conditions!=null)for(int i=0;i<conditions.length();i++)add(conditions.optJSONObject(i));
  parent.addView(AiosUi.textButton(a,a.getString(R.string.filter_add),()->{if(values.size()<20)add(null);}));
 }
 void add(JSONObject c){Row row=new Row(c);values.add(row);rows.addView(row.box);}
 JSONObject snapshot(){JSONObject t=new JSONObject();try{write(t,false);}catch(Exception e){throw new IllegalStateException(e);}return t;}
 void write(JSONObject t)throws Exception{write(t,true);}
 void write(JSONObject t,boolean validate)throws Exception{JSONArray out=new JSONArray();for(Row row:values){if(validate&&(row.value.getText().length()==0||row.value.getText().length()>500))throw new IllegalArgumentException(a.getString(R.string.filter_invalid));out.put(new JSONObject().put("field",fields[row.field.getSelectedItemPosition()]).put("op",ops[row.op.getSelectedItemPosition()]).put("value",row.value.getText().toString()).put("ignore_case",AiosUi.isChecked(row.ignore)));}t.put("conditions",out).put("condition_mode",mode.getSelectedItemPosition()==0?"all":"any");}
 class Row {
  final LinearLayout box,ignore;final AiosUi.Choice field,op;final EditText value;
  Row(JSONObject c){box=AiosUi.column(a);field=new AiosUi.Choice(a,new String[]{a.getString(R.string.filter_title),a.getString(R.string.filter_text)},c!=null&&c.optString("field").equals("text")?1:0,null);box.addView(field.view);
   String[] labels={a.getString(R.string.filter_contains),a.getString(R.string.filter_not_contains),a.getString(R.string.filter_equals),a.getString(R.string.filter_starts_with),a.getString(R.string.filter_ends_with)};int selected=c==null?0:Math.max(0,Arrays.asList(ops).indexOf(c.optString("op")));op=new AiosUi.Choice(a,labels,selected,null);box.addView(op.view);
   value=AiosUi.field(a,a.getString(R.string.filter_value),c==null?"":c.optString("value"));box.addView(value);ignore=AiosUi.switchRow(a,a.getString(R.string.filter_case),null,c==null||c.optBoolean("ignore_case",true),null);box.addView(ignore);
   box.addView(AiosUi.textButton(a,a.getString(R.string.filter_remove),()->{values.remove(this);rows.removeView(box);}));
  }
 }
}

